// Security headers for client sites. Dependency-free on purpose: a site's
// next.config.ts imports this subpath, so it must never pull in the database
// client or anything else heavy.

export type SecurityHeader = { key: string; value: string }

export type SecurityHeadersOptions = {
	/** Default 'SAMEORIGIN'. `false` omits X-Frame-Options. */
	frameOptions?: 'DENY' | 'SAMEORIGIN' | false
	/**
	 * Extra origins allowed to frame the site, added to CSP frame-ancestors
	 * ('self' is always first). When non-empty and `frameOptions` is not set,
	 * X-Frame-Options is omitted because it cannot express an allowlist.
	 */
	frameAncestors?: string[]
	/** Default 'strict-origin-when-cross-origin'. `false` omits the header. */
	referrerPolicy?: string | false
	csp?: {
		/** Default 'report-only'. */
		mode?: 'report-only' | 'enforce' | 'off'
		/** Extra sources appended per directive, deduped. */
		extend?: Partial<Record<string, string[]>>
		/** Directive fully replaced. */
		replace?: Partial<Record<string, string[]>>
		/** Adds a report-uri directive. */
		reportUri?: string
	}
	/** Appended; the same key (case-insensitive) overrides a default. */
	extraHeaders?: SecurityHeader[]
}

const DEFAULT_DIRECTIVES: Record<string, string[]> = {
	'default-src': ["'self'"],
	'script-src': [
		"'self'",
		"'unsafe-inline'",
		"'unsafe-eval'",
		'https://www.googletagmanager.com',
		'https://www.google-analytics.com',
	],
	'style-src': ["'self'", "'unsafe-inline'", 'https://fonts.googleapis.com'],
	'img-src': ["'self'", 'data:', 'blob:', 'https:'],
	'font-src': ["'self'", 'data:', 'https://fonts.gstatic.com'],
	'connect-src': [
		"'self'",
		'https://www.google-analytics.com',
		'https://*.google-analytics.com',
		'https://*.analytics.google.com',
		'https://www.googletagmanager.com',
	],
	'frame-src': [
		"'self'",
		'https://www.youtube.com',
		'https://www.youtube-nocookie.com',
		'https://player.vimeo.com',
		'https://calendly.com',
		'https://cal.com',
	],
	'frame-ancestors': ["'self'"],
	'base-uri': ["'self'"],
	'form-action': ["'self'"],
	'object-src': ["'none'"],
}

function dedupe(values: string[]): string[] {
	return [...new Set(values)]
}

export function buildContentSecurityPolicy(opts: SecurityHeadersOptions = {}): string {
	const csp = opts.csp ?? {}
	const directives = new Map<string, string[]>()
	for (const [name, sources] of Object.entries(DEFAULT_DIRECTIVES)) {
		directives.set(name, [...sources])
	}
	const ancestors = opts.frameAncestors ?? []
	if (ancestors.length > 0) {
		directives.set('frame-ancestors', dedupe(["'self'", ...ancestors]))
	}
	for (const [name, sources] of Object.entries(csp.replace ?? {})) {
		if (sources) directives.set(name, dedupe(sources))
	}
	for (const [name, sources] of Object.entries(csp.extend ?? {})) {
		if (!sources || sources.length === 0) continue
		directives.set(name, dedupe([...(directives.get(name) ?? []), ...sources]))
	}
	if (csp.reportUri) directives.set('report-uri', [csp.reportUri])
	return [...directives.entries()]
		.map(([name, sources]) => (sources.length > 0 ? `${name} ${sources.join(' ')}` : name))
		.join('; ')
}

export function securityHeaders(opts: SecurityHeadersOptions = {}): SecurityHeader[] {
	const headers: SecurityHeader[] = [{ key: 'X-Content-Type-Options', value: 'nosniff' }]

	const hasAncestors = (opts.frameAncestors ?? []).length > 0
	const frameOptions = opts.frameOptions ?? (hasAncestors ? false : 'SAMEORIGIN')
	if (frameOptions) headers.push({ key: 'X-Frame-Options', value: frameOptions })

	const referrer = opts.referrerPolicy ?? 'strict-origin-when-cross-origin'
	if (referrer) headers.push({ key: 'Referrer-Policy', value: referrer })

	const mode = opts.csp?.mode ?? 'report-only'
	if (mode !== 'off') {
		headers.push({
			key: mode === 'enforce' ? 'Content-Security-Policy' : 'Content-Security-Policy-Report-Only',
			value: buildContentSecurityPolicy(opts),
		})
	}

	for (const extra of opts.extraHeaders ?? []) {
		const lower = extra.key.toLowerCase()
		const idx = headers.findIndex((h) => h.key.toLowerCase() === lower)
		if (idx >= 0) headers.splice(idx, 1)
		headers.push({ key: extra.key, value: extra.value })
	}
	return headers
}
